buildGradleAdditions.insert:
repositories {
  maven {
    url 'https://nexus-external.rustore.ru/repository/maven-rustore-exposed'
  }
}

ext.review_type = ''

if (project.hasProperty('rustore_sdk_type')) {
  review_type = rustore_sdk_type
}

dependencies {
  // RuStore Review
  implementation("ru.rustore.sdk:review:10.5.1$review_type")
  implementation fileTree(include: ["RuStoreUnrealReview${review_type}.aar"], dir: 'src/main/libs')
}
